CREATE TABLE IF NOT EXISTS `devhub_racing_races` (
`id` int(11) NOT NULL AUTO_INCREMENT,
`mapId` int(11) NOT NULL,
`startTime` timestamp NOT NULL,
`laps` tinyint(4) DEFAULT NULL,
`collisions` tinyint(4) NOT NULL DEFAULT 1,
`entryFee` int(11) NOT NULL DEFAULT 0,
`fpv` int(11) NOT NULL DEFAULT 0,
`vehicleClass` enum('ALL','S','A','B','C','D') NOT NULL DEFAULT 'ALL',
`official` varchar(100) DEFAULT NULL,
`winnerReward` int(11) NOT NULL DEFAULT 0,
`creatorIdentifier` varchar(255) DEFAULT NULL,
`createdAt` datetime NOT NULL DEFAULT current_timestamp(),
PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `devhub_racing_users` (
`identifier` varchar(46) NOT NULL,
`name` varchar(100) NOT NULL DEFAULT 'user',
`image` longtext NOT NULL DEFAULT '',
`mmr` int(11) NOT NULL DEFAULT 1500,
`stats` longtext NOT NULL DEFAULT '{}',
`achievements` longtext NOT NULL DEFAULT '{}',
`favoriteMaps` longtext NOT NULL DEFAULT '{}',
`votedMaps` longtext NOT NULL DEFAULT '{}',
PRIMARY KEY (`identifier`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci ROW_FORMAT=DYNAMIC;

CREATE TABLE IF NOT EXISTS `devhub_racing_maps` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(150) NOT NULL DEFAULT 'Default',
  `start` longtext NOT NULL DEFAULT '{}',
  `finish` longtext NOT NULL DEFAULT '{}',
  `checkpoints` longtext NOT NULL DEFAULT '{}',
  `decorations` longtext NOT NULL DEFAULT '{}',
  `raceType` enum('loop','sprint') NOT NULL DEFAULT 'loop',
  `isVerified` tinyint(4) NOT NULL DEFAULT 0,
  `rating` longtext NOT NULL DEFAULT '{}',
  `creator` varchar(255) NOT NULL DEFAULT 'SYSTEM',
  `creatorIdentifier` varchar(255) DEFAULT NULL,
  `playCount` int(11) NOT NULL DEFAULT 0,
  `stats` longtext DEFAULT '{}',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_general_ci ROW_FORMAT=DYNAMIC;

